package com.aoo.bcg.common.repair;import java.time.Duration;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ThrottledRepairRunnerTest{@Test void pausesAndResumesFromExactCheckpoint()throws Exception{var runner=new ThrottledRepairRunner<Integer>(2,1000000,"maintenance-repair");var seen=new ArrayList<Integer>();var first=runner.run(List.of(1,2,3,4),new ThrottledRepairRunner.Checkpoint(0,0,0,false),n->{seen.add(n);if(n==2)runner.pause();},Duration.ZERO);assertTrue(first.paused());assertEquals(2,first.offset());runner.resume();var end=runner.run(List.of(1,2,3,4),first,seen::add,Duration.ZERO);assertEquals(4,end.offset());assertEquals(List.of(1,2,3,4),seen);assertThrows(IllegalArgumentException.class,()->new ThrottledRepairRunner<>(1,1,"live-game"));}}
